#include <bits/stdc++.h>
using namespace std;
const int m = 998244353;


void solve()
{
    int n;
    cin >> n;
    vector<vector<int>>p(n + 1);
    for(int i = 1; i <= n; i++)
    {
        int x;
        cin >> x;
        p[x].push_back(i);
    }
    vector<int>d(n + 1), e(n + 1);
    d[0] = 1;
    for(int i = 1; i <= n; i++)
    {
        fill(e.begin(), e.end(), 0);
        // e[0] = 0;
        
        for(int j = 0; j < i; j++)
        {
            if(!d[j])
                continue;
            int r= n - i + 1 + j;
            for(int k = 0; k < (i == n ? 1 : 2); k++)
            {
                // int q = k + j;
                int q = k == 0 ? j + 1 : r;
                bool b = true;
                for(int x : p[i])
                {
                    int u = min(j, x) + max(0, x - r);
                    int v = max(0, j - x + 1) + min(n - r, n - x + 1);
                    
                    
                    if((q <= x and u == (x - 1)/ 2) or (q >= x and v ==(n - x)/ 2))
                    {
                        continue;
                    }
                    b = false;
                    break;
                }
                if(b)
                {
                    int z = j + (k == 0);
                    e[z] += d[j];
                    if(e[z] >= m)
                        e[z] -= m;
                }
            }
                
        }
        d.swap(e);
    }
    int s = 0, ff = 0;
    for(int x : d)
    {
        s += x;
        if(s >= m)
            s-= m;
    }
    cout << s << endl;
}




int main() {
	// your code goes here
	int t;
	cin >> t;
	while(t--)
	    solve();

}
